import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/getting-started.md","filePath":"user-guide/getting-started.md","lastUpdated":1785465582000}'),i={name:"user-guide/getting-started.md"};function n(s,e,l,h,d,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><h2 id="installing" tabindex="-1">Installing <a class="header-anchor" href="#installing" aria-label="Permalink to &quot;Installing&quot;">​</a></h2><p>Grab the latest release from the <a href="./../">download button</a> on the homepage — two flavors are published for every release:</p><ul><li><strong>Installer</strong> (<code>SwiftList-Setup.exe</code>) — recommended. It registers the background indexing service and can start SwiftList with Windows.</li><li><strong>Portable</strong> (<code>SwiftList-Portable.zip</code>) — unzip and run, no installation. You can still install the background service later from <strong>Settings → Service Status</strong>. If your machine doesn&#39;t already have the .NET Desktop Runtime SwiftList needs, run the included <code>install-dotnet-runtime.bat</code> once — the Installer handles this step automatically, but the portable build can&#39;t. When you&#39;re done with a portable install, there&#39;s no uninstaller to clean up after you: double-click the included <code>portable-cleanup-registry.reg</code> (confirm the prompt) before deleting the folder to remove the two per-user registry entries SwiftList creates on its own — the <code>swiftlist://</code> URI protocol registration and its &quot;start with Windows&quot; entry. Both are per-user (HKCU) only, so no administrator prompt is needed.</li></ul><p>Each of those is published for <strong>x64</strong> and for <strong>ARM64</strong>. The names above are the x64 builds, which run on any recent PC — including Windows on ARM, where they run emulated. On an ARM machine prefer <code>SwiftList-Setup_arm64.exe</code> or <code>SwiftList-Portable_arm64.zip</code>, which are native. Automatic updates stay on the architecture you installed, so moving between them means downloading the other build yourself.</p><p>On first run, SwiftList installs and starts a Windows service (<code>SwiftList.Service</code>) that owns file indexing. This split exists on purpose — see <a href="./../dev-guide/architecture.html">Architecture</a> if you&#39;re curious why — but as a user, the only thing you need to know is: <strong>Settings → Service Status</strong> tells you whether the service is installed and running, and lets you install it if it isn&#39;t.</p><h2 id="the-three-windows" tabindex="-1">The three windows <a class="header-anchor" href="#the-three-windows" aria-label="Permalink to &quot;The three windows&quot;">​</a></h2><p>SwiftList doesn&#39;t have just one search window — it adapts to how you&#39;re using it:</p><ul><li><strong>Main window</strong> — the full window you get from the taskbar/Start Menu shortcut, with the largest result list and an in-window Actions panel.</li><li><strong>Quick window</strong> — the compact, always-on-top popup you summon with the global toggle hotkey (double-tap <code>Ctrl</code> by default). Built for &quot;hit hotkey → type → Enter&quot; muscle memory.</li><li><strong>Inline window</strong> — embeds a SwiftList search bar directly into a supported native file dialog or File Explorer window, so you can search without leaving the dialog you&#39;re already in.</li></ul><p>All three share the same search engine, hotkey system, and Actions menu — the difference is purely where and how they appear.</p><h2 id="basic-search" tabindex="-1">Basic search <a class="header-anchor" href="#basic-search" aria-label="Permalink to &quot;Basic search&quot;">​</a></h2><p>Clearing the search box (or opening the quick window fresh) shows the <a href="./settings/startup-panel.html">Startup Panel</a> instead of an empty result list — a tab strip with quick access to recent files, favorites, and history, no query needed.</p><p>Just start typing. Results update as you type, ranked by relevance (see <a href="./search-syntax.html">Search Syntax</a> for how matching and ranking work). Use the <a href="./hotkeys.html">configurable next/previous-item hotkeys</a> (arrow keys by default) to move the selection, and Enter to open the highlighted result.</p><p>Next up: <a href="./search-syntax.html">Search Syntax</a> to get the most out of the query box.</p>',14)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
